// tb_StdpWriteback_q88.sv
// Canonical source: spikenaut-core-sv/tb
// Q8.8 saturation-boundary golden testbench for StdpWriteback.sv driving a
// real WeightRam (closed-loop read / modify / write).
//
// Every stimulus word and every expectation comes from
// spikenaut-core-sv/mem/golden/q88b_wb_*.mem, generated by
// scripts/gen_golden_q88_boundary.py from a bit-exact Python model built on
// scripts/q88.py. Nothing is asserted from hand-written constants here.
//
// Vectors come in groups of NUM_NEURONS (4) sharing one op. Per group the
// engine is reset (traces cleared), column COL of the 4x4 RAM is seeded with
// the group's four boundary weights (one per post row), every other cell is
// seeded with a sentinel, and two closed-loop ticks select the op (same
// sequencing as tb_StdpController_q88, with every post neuron spiking
// together). After the second sweep each seeded cell must hold the golden
// word, and a RAM write strobe must have been seen on that cell iff the
// golden write enable is 1. Sentinel cells must never be written.
//
// Run from the repo root (golden paths are repo-root relative).
// Stimulus and checks run on negedge clk, matching every other core TB.

`timescale 1ns/1ps

module tb_StdpWriteback_q88 #(
    parameter string WEIGHT_FILE = "spikenaut-core-sv/mem/golden/q88b_wb_weight_in.mem",
    parameter string OP_FILE     = "spikenaut-core-sv/mem/golden/q88b_wb_op.mem",
    parameter string EXP_W_FILE  = "spikenaut-core-sv/mem/golden/q88b_wb_exp_weight.mem",
    parameter string EXP_WE_FILE = "spikenaut-core-sv/mem/golden/q88b_wb_exp_we.mem",
    parameter string COUNT_FILE  = "spikenaut-core-sv/mem/golden/q88b_wb_count.mem"
);

    localparam int DATA_WIDTH   = 16;
    localparam int NUM_NEURONS  = 4;
    localparam int INDEX_WIDTH  = 2;
    localparam int ADDR_WIDTH   = 4;
    localparam int WINDOW_WIDTH = 8;
    localparam int CLK_PERIOD   = 10;
    localparam int COL          = 1;
    localparam int MAX_VECTORS  = 512;
    localparam logic [DATA_WIDTH-1:0] SENTINEL = 16'h5A5A;

    logic                    clk;
    logic                    rst_n;
    logic                    learn_en;
    logic                    step_en;
    logic                    tick_done;
    logic                    pre_spike;
    logic [NUM_NEURONS-1:0]  post_spikes;
    logic [INDEX_WIDTH-1:0]  input_index;
    logic [DATA_WIDTH-1:0]   weight_dout;
    logic                    busy;
    logic                    weight_we;
    logic [ADDR_WIDTH-1:0]   weight_addr;
    logic [DATA_WIDTH-1:0]   weight_din;

    int errors = 0;
    int n_vectors;

    logic [15:0] w_vec     [0:MAX_VECTORS-1];
    logic [15:0] op_vec    [0:MAX_VECTORS-1];
    logic [15:0] exp_w_vec [0:MAX_VECTORS-1];
    logic [15:0] exp_we_vec[0:MAX_VECTORS-1];
    logic [15:0] count_vec [0:0];

    // Write monitor: which RAM cells saw a write strobe this group.
    logic [(1<<ADDR_WIDTH)-1:0] wrote;
    logic                       clear_wrote;

    WeightRam #(
        .ADDR_WIDTH (ADDR_WIDTH),
        .DATA_WIDTH (DATA_WIDTH),
        .INIT_FILE  ("NONE")
    ) u_wram (
        .clk   (clk),
        .rst_n (rst_n),
        .we    (weight_we),
        .addr  (weight_addr),
        .din   (weight_din),
        .dout  (weight_dout)
    );

    StdpWriteback #(
        .DATA_WIDTH   (DATA_WIDTH),
        .NUM_NEURONS  (NUM_NEURONS),
        .ADDR_WIDTH   (ADDR_WIDTH),
        .WINDOW_WIDTH (WINDOW_WIDTH)
    ) dut (
        .clk          (clk),
        .rst_n        (rst_n),
        .learn_en     (learn_en),
        .step_en      (step_en),
        .tick_done    (tick_done),
        .pre_spike    (pre_spike),
        .post_spikes  (post_spikes),
        .input_index  (input_index),
        .weight_dout  (weight_dout),
        .busy         (busy),
        .weight_we    (weight_we),
        .weight_addr  (weight_addr),
        .weight_din   (weight_din)
    );

    initial clk = 1'b0;
    always #(CLK_PERIOD/2) clk = ~clk;

    always @(posedge clk) begin
        if (clear_wrote)
            wrote <= '0;
        else if (rst_n && weight_we)
            wrote[weight_addr] <= 1'b1;
    end

    task automatic require_file(input string path);
        int fd;
        fd = $fopen(path, "r");
        if (fd == 0)
            $fatal(1, "TB_STDPWRITEBACK_Q88: cannot open '%s' (run from the repo root)", path);
        $fclose(fd);
    endtask

    task automatic wait_idle();
        int unsigned waited;
        begin
            waited = 0;
            while (busy === 1'b1) begin
                @(negedge clk);
                waited++;
                if (waited > 8 * NUM_NEURONS + 8)
                    $fatal(1, "TB_STDPWRITEBACK_Q88: still busy after %0d cycles", waited);
            end
        end
    endtask

    // One logical tick: step_en with this tick's pre, then tick_done with the
    // post bitmap a few fabric cycles later (LifNeuronArray ordering), then
    // wait for the column sweep to finish.
    task automatic closed_loop_tick(input logic pre, input logic post_all);
        begin
            step_en     = 1'b1;
            pre_spike   = pre;
            @(negedge clk);
            step_en     = 1'b0;
            pre_spike   = 1'b0;
            repeat (3) @(negedge clk);
            post_spikes = post_all ? '1 : '0;
            tick_done   = 1'b1;
            @(negedge clk);
            tick_done   = 1'b0;
            post_spikes = '0;
            wait_idle();
        end
    endtask

    initial begin
        int n_groups;

        require_file(WEIGHT_FILE);
        require_file(OP_FILE);
        require_file(EXP_W_FILE);
        require_file(EXP_WE_FILE);
        require_file(COUNT_FILE);

        $readmemh(WEIGHT_FILE, w_vec);
        $readmemh(OP_FILE,     op_vec);
        $readmemh(EXP_W_FILE,  exp_w_vec);
        $readmemh(EXP_WE_FILE, exp_we_vec);
        $readmemh(COUNT_FILE,  count_vec);

        n_vectors = int'(count_vec[0]);
        if (n_vectors <= 0 || n_vectors > MAX_VECTORS || (n_vectors % NUM_NEURONS) != 0)
            $fatal(1, "TB_STDPWRITEBACK_Q88: vector count %0d must be a multiple of %0d in 1..%0d",
                   n_vectors, NUM_NEURONS, MAX_VECTORS);
        n_groups = n_vectors / NUM_NEURONS;

        begin : vacuity_guard
            automatic bit saw_we = 1'b0;
            automatic bit saw_sat = 1'b0;
            for (int i = 0; i < n_vectors; i++) begin
                if (exp_we_vec[i] == 16'd1) saw_we = 1'b1;
                if (op_vec[i] == 16'd2 && w_vec[i] == 16'h8000) saw_sat = 1'b1;
            end
            if (!saw_we || !saw_sat)
                $fatal(1, "TB_STDPWRITEBACK_Q88: golden images look empty or unloaded");
        end

        $display("TB_STDPWRITEBACK_Q88: replaying %0d boundary vectors in %0d groups", n_vectors, n_groups);

        learn_en    = 1'b1;
        step_en     = 1'b0;
        tick_done   = 1'b0;
        pre_spike   = 1'b0;
        post_spikes = '0;
        input_index = INDEX_WIDTH'(COL);
        clear_wrote = 1'b0;

        for (int g = 0; g < n_groups; g++) begin
            automatic int base = g * NUM_NEURONS;
            automatic logic [15:0] op = op_vec[base];
            logic t1_pre, t1_post, t2_pre, t2_post;

            for (int k = 1; k < NUM_NEURONS; k++)
                if (op_vec[base + k] !== op)
                    $fatal(1, "TB_STDPWRITEBACK_Q88: group %0d does not have a uniform op", g);

            case (op)
                16'd0: begin t1_pre = 1; t1_post = 0; t2_pre = 0; t2_post = 0; end
                16'd1: begin t1_pre = 1; t1_post = 0; t2_pre = 0; t2_post = 1; end
                16'd2: begin t1_pre = 0; t1_post = 1; t2_pre = 1; t2_post = 0; end
                16'd3: begin t1_pre = 1; t1_post = 1; t2_pre = 1; t2_post = 1; end
                default: $fatal(1, "TB_STDPWRITEBACK_Q88: group %0d has unknown op %0d", g, op);
            endcase

            rst_n = 1'b0;
            repeat (2) @(negedge clk);
            for (int a = 0; a < (1 << ADDR_WIDTH); a++)
                u_wram.mem[a] = SENTINEL;
            for (int n = 0; n < NUM_NEURONS; n++)
                u_wram.mem[n * NUM_NEURONS + COL] = w_vec[base + n];
            rst_n = 1'b1;
            @(negedge clk);

            // Trace-load tick: traces empty, so no cell may change.
            closed_loop_tick(t1_pre, t1_post);
            for (int n = 0; n < NUM_NEURONS; n++)
                if (u_wram.mem[n * NUM_NEURONS + COL] !== w_vec[base + n]) begin
                    errors++;
                    $display("FAIL group %0d row %0d: trace-load tick changed %04h -> %04h",
                             g, n, w_vec[base + n], u_wram.mem[n * NUM_NEURONS + COL]);
                end

            clear_wrote = 1'b1;
            @(negedge clk);
            clear_wrote = 1'b0;

            closed_loop_tick(t2_pre, t2_post);

            for (int n = 0; n < NUM_NEURONS; n++) begin
                automatic int idx  = base + n;
                automatic int addr = n * NUM_NEURONS + COL;
                if (u_wram.mem[addr] !== exp_w_vec[idx]) begin
                    errors++;
                    $display("FAIL vector %0d (group %0d row %0d op %0d): RAM %04h -> %04h, golden %04h",
                             idx, g, n, op, w_vec[idx], u_wram.mem[addr], exp_w_vec[idx]);
                end
                if (wrote[addr] !== exp_we_vec[idx][0]) begin
                    errors++;
                    $display("FAIL vector %0d (group %0d row %0d op %0d): weight %04h write strobe %0b, golden %0b",
                             idx, g, n, op, w_vec[idx], wrote[addr], exp_we_vec[idx][0]);
                end
            end
            for (int a = 0; a < (1 << ADDR_WIDTH); a++)
                if ((a % NUM_NEURONS) != COL && (wrote[a] !== 1'b0 || u_wram.mem[a] !== SENTINEL)) begin
                    errors++;
                    $display("FAIL group %0d: off-column cell %0d was written (now %04h)", g, a, u_wram.mem[a]);
                end
        end

        if (errors == 0) begin
            $display("TB_STDPWRITEBACK_Q88: ALL %0d BOUNDARY VECTORS MATCHED", n_vectors);
            $finish;
        end else begin
            $display("TB_STDPWRITEBACK_Q88: %0d MISMATCH(ES)", errors);
            $display("  Regenerate only for an intended semantics change: python3 scripts/gen_golden_q88_boundary.py");
            $fatal(1, "TB_STDPWRITEBACK_Q88: testbench FAILED");
        end
    end

endmodule
